function changeDetailTab(tab,column){DETAIL_TAB=['overview','prices','dates','history'].includes(tab)?tab:'overview';if(column)DETAIL_COLUMN=column;renderVoyage();requestAnimationFrame(()=>$('tab-'+DETAIL_TAB)?.focus({preventScroll:true}));}
function baseChart(){const c=palette();return {responsive:true,maintainAspectRatio:false,animation:false,plugins:{legend:{display:false},tooltip:{backgroundColor:c.ink,titleColor:c.bg,bodyColor:c.bg,padding:11,displayColors:false,titleFont:{size:13},bodyFont:{size:13}}},scales:{x:{grid:{display:false},border:{color:c.line},ticks:{color:c.muted,font:{size:12},maxTicksLimit:7}},y:{grid:{color:c.line,drawTicks:false},border:{display:false},ticks:{color:c.muted,font:{size:12},padding:8,callback:v=>fmtGBP.format(v/100)}}}}}
