 const good=months.some(m=>m.count);$('calendarChart').hidden=!good;$('calendarFallback').innerHTML=good?'':'<div class="notice">No matching departures in this year. Choose another calendar year or broaden your date filters.</div>';if(!good)return;
 if(!window.Chart){$('calendarFallback').innerHTML='<p class="notice">The chart could not load. All monthly values are available in the data table.</p>';$('calendarChart').hidden=true;return}
 const c=palette(),opt=baseChart();opt.scales.y.beginAtZero=true;opt.plugins.tooltip.callbacks={title:items=>months[items[0].dataIndex].label+' '+year,label:ctx=>money(ctx.raw)+' for two · '+months[ctx.dataIndex].source,afterLabel:ctx=>months[ctx.dataIndex].count+' matching products · Select month'};
