 if(!rows.length){toast('Select a current departure before preparing questions. Historical records remain available in price history.');return}
 if(rows.length<selected.length)toast('Questions include current departures only. Historical records stay in your comparison.');
 $('comparisonQuestionText').value=globalThis.ORIONQuestions.build(rows,DATA.feed.observed_at,{category:state.cabin||'',guides:Object.fromEntries(rows.map(r=>[r.id,fare(r)]))});
 modalClose('comparisonDialog');modalOpen('questionDialog');$('comparisonQuestionText').focus();
