$('voyageDialog')?.addEventListener('change',e=>{if(['archiveSeries','sellerSeries'].includes(e.target.id)){const id=e.target.id;ARCHIVE_SERIES=e.target.value;REQUESTED_SELLER_POINT='';renderVoyage();requestAnimationFrame(()=>$(id)?.focus({preventScroll:true}))}});

let EDITION_POLL_RUNNING=false;
function refreshCalendarDate(){
 const next=londonToday();if(!DATA||next<=today)return false;
 today=next;installCatalogueRows(DATA);
 if(DETAIL)DETAIL=C.retiredProduct(DETAIL,today,DATA.feed?.observed_at);
 return true;
}
async function refreshPublishedEdition(){
 refreshAgentEligibility();
 if(refreshCalendarDate()){
  render();if(DETAIL&&$('voyageDialog')?.open)renderVoyage();
  if($('comparisonDialog')?.open)openComparison();
  if($('watchDialog')?.open&&WATCH_EDIT_ID&&(!BY_ID.has(WATCH_EDIT_ID)||isRetired(BY_ID.get(WATCH_EDIT_ID)))){WATCH_EDIT_ID=null;renderWatches();}
 }
 if(DATA)renderFreshness();
 if(EDITION_POLL_RUNNING||document.hidden||!DATA||catalogueUpdateBlocked())return;
 EDITION_POLL_RUNNING=true;
 try{
  const r=await fetch(new URL('release.json',base),{cache:'no-cache'});if(!r.ok)return;
  const v=await r.json(),meta=document.querySelector('meta[name=orion-catalogue]');
  const current=C.timestamp(DATA.built_at),incoming=C.timestamp(v.built_at);
  if(C.dataPath(v.data_file)&&v.data_file.startsWith('data/catalogue.')&&meta.content!==v.data_file&&incoming!==null&&incoming<=Date.now()&&(current===null||incoming>current)){
   if(await loadCatalogue(v.data_file,v))toast('Updated published prices loaded. Your filters and saved voyages are kept.');
  }
 }catch(e){console.warn('ORION edition refresh deferred:',e.message)}finally{EDITION_POLL_RUNNING=false}
}
function refreshAgentEligibility(){
 if(!DATA||document.hidden)return;
 const signature=PRODUCTS.flatMap(r=>agentOffers(r).map(a=>a.id)).join(',');
 if(signature===AGENT_PRICE_SIGNATURE)return;
 AGENT_PRICE_SIGNATURE=signature;render();
 if(DETAIL&&$('voyageDialog')?.open)renderVoyage();
 if($('comparisonDialog')?.open)openComparison();
}
setInterval(refreshAgentEligibility,60*1000);
setInterval(refreshPublishedEdition,5*60*1000);window.addEventListener('focus',refreshPublishedEdition);
function saveWatchState(){const a=store.write('watches',watches),b=store.write('watchEvents',watchEvents);if(!a||!b)toast('Price watch is available this visit only. Browser storage is unavailable.');const n=watchEvents.filter(x=>!x.viewedAt).length;$('watchBadge').textContent=n;$('watchBadge').hidden=!n;}
function watchValidationAt(){return C.freshness(DATA).confirmationAt;}
function assessWatches(redraw=true){if(!W||!DATA)return;refreshCalendarDate();const r=W.evaluate(watches,PRODUCTS,DATA.feed.observed_at,watchEvents,Date.now(),watchValidationAt());watches=r.watches;watchStates=r.states;watchEvents=[...r.events,...watchEvents].slice(0,100);saveWatchState();if(r.events.length){toast(r.events.length+' watched price change'+(r.events.length===1?'':'s')+' found. Recheck with the seller.');for(const e of r.events)sendDesktopNotice(e)}if(redraw&&$('watchDialog')?.open)renderWatches();}
function sendDesktopNotice(event){if(!('Notification' in window)||Notification.permission!=='granted')return;try{const n=new Notification(event.test?'ORION delivery test':'Watched Windstar price changed',{body:event.test?'This is a test, not a cruise bargain.':event.itinerary+': '+money(event.currentPence)+' estimated for two. Verify before booking.',tag:event.id,icon:new URL('assets/favicon.svg',base).href});event.browserNotice='requested';n.onshow=()=>{event.browserNotice='browser_reported_shown';saveWatchState()};n.onclick=()=>{window.focus();openWatches();n.close()};n.onerror=()=>{event.browserNotice='failed';saveWatchState()};saveWatchState()}catch{event.browserNotice='unsupported_or_failed';saveWatchState()}}
function openWatches(product,column=''){
 refreshCalendarDate();if(product&&isRetired(product)){toast('This departure is historical. Its price record is retained.');return}
 WATCH_EDIT_ID=product?.id||null;WATCH_EDIT_COLUMN=column||state.cabin||(product?supplierRate(product)?.column:'')||product?.fares?.[0]?.[0]||'';
 if(product)modalClose('voyageDialog');assessWatches(false);renderWatches(product);
 for(const e of watchEvents)if(!e.viewedAt)e.viewedAt=new Date().toISOString();saveWatchState();modalOpen('watchDialog');
}
function watchEditorStatus(product){
 const column=$('watchColumn')?.value,amount=W.amount(product,column),fresh=C.freshness(DATA).feedFresh;
 if($('watchCurrentAmount'))$('watchCurrentAmount').textContent=amount===null?'No published price':money(amount*2);
 if($('watchSaveStatus'))$('watchSaveStatus').textContent=amount===null?'This category has no current price. Your existing target is kept.':fresh?'Save here. We check new published prices while this page is open.':'You can save a target now. Checks will begin after a fresh price update.';
 const save=$('watchForm')?.querySelector('button[type=submit]');if(save)save.disabled=amount===null;
}
function watchStatus(w,state){
 if(!w.enabled)return 'Paused';const specific={voyage_missing:'Not in the latest catalogue',category_missing:'No current price in this category',departed:'Departure has passed',retired:'Departure no longer listed',invalid_watch:'Saved target needs review',price_timestamp_conflict:'Conflicting evidence · check seller'};if(specific[state])return specific[state];if(w.pendingValidation)return 'Target saved · waiting for a fresh check';
 if(state==='stale_snapshot'&&w.targetPence&&w.lastPrice*2<=w.targetPence)return 'Last check met your target · update overdue';
 return {stale_snapshot:'Waiting for a fresh update',older_snapshot:'Keeping newer saved evidence',price_timestamp_conflict:'Conflicting evidence · check seller',voyage_missing:'Not in the latest catalogue',category_missing:'No current price in this category',departed:'Departure has passed',retired:'Departure no longer listed',condition_met:'Target condition met',target_already_met:'Latest checked price meets your target',activated:'Ready for the next price update'}[state]||(w.targetPence&&w.lastPrice*2<=w.targetPence?'Latest recorded price meets your target':'Checking new published prices');
}
